import 'dart:io';

import 'package:path/path.dart' as p;
import 'package:test/test.dart';

// The generator is imported so the test checks the real thing, not a copy.
import '../tool/generate_guidance.dart';

/// `guidance/` is the one source for the three agent-facing texts:
/// `serverInstructions`, the `flutterpilot_guide` prompt and
/// `skills/flutterpilot/SKILL.md`. This fails when a generated file is stale,
/// so a hand edit to a generated file cannot survive (run
/// `dart run tool/generate_guidance.dart`).
void main() {
  final packageRoot = Directory.current;
  final repoRoot = packageRoot.parent.parent;
  final guidance = Directory(p.join(packageRoot.path, 'guidance'));

  String normalized(String text) => text.replaceAll('\r\n', '\n');

  test('lib/src/generated/guidance.g.dart is what guidance/ generates', () {
    final file = File(
      p.join(packageRoot.path, 'lib/src/generated/guidance.g.dart'),
    );
    expect(file.existsSync(), isTrue);
    expect(
      normalized(file.readAsStringSync()),
      normalized(renderGuidanceDart(packageRoot)),
      reason: 'Run: dart run tool/generate_guidance.dart',
    );
  });

  test('skills/flutterpilot/SKILL.md is what guidance/ generates', () {
    final file = File(p.join(repoRoot.path, 'skills/flutterpilot/SKILL.md'));
    expect(file.existsSync(), isTrue);
    expect(
      normalized(file.readAsStringSync()),
      normalized(renderSkill(packageRoot)),
      reason: 'Run: dart run tool/generate_guidance.dart',
    );
  });

  test('the server sends the generated instructions, not a copy', () {
    // mcp_dart puts the Server's instructions into the InitializeResult, which
    // is what every connecting client receives (checked over the wire in the
    // PR). `McpServer` keeps them private, so this reads the wiring.
    final source = File(
      p.join(packageRoot.path, 'lib/flutterpilot_server.dart'),
    ).readAsStringSync();
    expect(source, contains('instructions: serverInstructions'));
    expect(source, isNot(contains("const serverInstructions = '''")));
  });

  test('the generated SKILL.md keeps its frontmatter first', () {
    final text = renderSkill(packageRoot);
    expect(text, startsWith('---\nname: flutterpilot\n'));
    expect(
      text,
      contains('<!-- Generated by tool/generate_guidance.dart'),
      reason: 'the note must come after the frontmatter, never before it',
    );
  });

  test('a marker with no partial fails instead of shipping', () {
    expect(
      () => expandIncludes('<!-- include: nope -->', loadPartials(guidance)),
      throwsStateError,
    );
  });

  test('partials are one level deep and expand in place', () {
    final temp = Directory.systemTemp.createTempSync('guidance_test');
    addTearDown(() => temp.deleteSync(recursive: true));
    Directory(p.join(temp.path, 'partials')).createSync();
    File(
      p.join(temp.path, 'partials/one.md'),
    ).writeAsStringSync('one sentence.\n');

    final partials = loadPartials(temp);
    expect(partials['one'], 'one sentence.');
    expect(
      expandIncludes('- <!-- include: one -->', partials),
      '- one sentence.',
    );

    // One level only: a partial may not include another.
    File(
      p.join(temp.path, 'partials/two.md'),
    ).writeAsStringSync('<!-- include: one -->\n');
    expect(() => loadPartials(temp), throwsStateError);
  });
}
